const raw = $input.first().json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch(e) {
  throw new Error('JSON inválido de OpenAI: ' + raw);
}
return [{ 
  json: { 
    prioridad: parsed.prioridad,
    categoria: parsed.categoria,
    borrador_respuesta: parsed.borrador_respuesta,
    estado: 'Procesado por IA',
    ticket_id: $('Crear Ticket en Airtable').first().json.fields.ticket_id
  } 
}];

